"""Data model and money logic for a kitty, independent of the command line.

All money is handled as Decimal and stored in kitty.json as strings with two
decimals, so nothing is ever lost to floating-point rounding. Each expense and
payment stores its value converted to the main currency at the time it was
added, so changing an exchange rate later does not rewrite past entries.
"""

import datetime
import json
import os
import re
import tempfile
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
HUNDRED = Decimal("100")
DATA_VERSION = 1

_AMOUNT_RE = re.compile(r"^\d+(\.\d{1,2})?$")
_NUMBER_RE = re.compile(r"^\d+(\.\d+)?$")
_CURRENCY_RE = re.compile(r"^[A-Z]{3}$")


class KittyError(Exception):
    """A problem caused by the user's input or data; shown as a plain message."""


# ---------------------------------------------------------------- parsing


def parse_amount(text, what="amount"):
    """A positive money amount with at most two decimals, e.g. '45' or '12.50'."""
    text = text.strip()
    if not _AMOUNT_RE.match(text):
        raise KittyError(
            "%s must be a positive number with at most two decimals, got %r" % (what, text)
        )
    value = Decimal(text)
    if value <= 0:
        raise KittyError("%s must be greater than zero, got %r" % (what, text))
    return value


def parse_positive_number(text, what):
    """A positive number with any number of decimals (rates, shares, percents)."""
    text = text.strip()
    if not _NUMBER_RE.match(text):
        raise KittyError("%s must be a positive number, got %r" % (what, text))
    value = Decimal(text)
    if value <= 0:
        raise KittyError("%s must be greater than zero, got %r" % (what, text))
    return value


def parse_currency(text):
    code = text.strip().upper()
    if not _CURRENCY_RE.match(code):
        raise KittyError("currency must be a three-letter code like EUR or USD, got %r" % text)
    return code


def parse_date(text):
    try:
        return datetime.date.fromisoformat(text.strip()).isoformat()
    except ValueError:
        raise KittyError("date must look like 2026-07-14, got %r" % text)


def today():
    return datetime.date.today().isoformat()


def validate_name(name):
    name = name.strip()
    if not name:
        raise KittyError("name cannot be empty")
    if "," in name or "=" in name:
        raise KittyError("name cannot contain ',' or '=', got %r" % name)
    return name


def money(value):
    """Format a Decimal as text with two decimals, never '-0.00'."""
    value = Decimal(value).quantize(CENT, rounding=ROUND_HALF_UP)
    if value == 0:
        value = Decimal("0.00")
    return "%s" % value


# --------------------------------------------------------------- splitting


def split_proportionally(total, weights):
    """Split `total` (a Decimal in cents) by `weights` so the parts add up exactly.

    `weights` is a list of (name, positive Decimal). Each person gets their
    share rounded down to the cent; the leftover cents go one at a time to the
    people whose shares were rounded down the most (ties: in the given order).
    """
    total_cents = int((total / CENT).to_integral_value())
    weight_sum = sum(w for _, w in weights)
    exact = [(name, Decimal(total_cents) * w / weight_sum) for name, w in weights]
    floors = [(name, int(e)) for name, e in exact]  # e >= 0, so int() floors
    leftover = total_cents - sum(c for _, c in floors)
    order = sorted(
        range(len(exact)), key=lambda i: (-(exact[i][1] - floors[i][1]), i)
    )
    cents = dict(floors)
    for i in order[:leftover]:
        cents[exact[i][0]] += 1
    return {name: Decimal(cents[name]) * CENT for name, _ in weights}


# ------------------------------------------------------------------ ledger


class Ledger:
    def __init__(self, data):
        self.data = data

    # ---- storage

    @classmethod
    def create(cls, path, base_currency):
        if os.path.exists(path):
            raise KittyError(
                "%s already exists here; delete or move it first to start a new kitty" % path
            )
        ledger = cls(
            {
                "version": DATA_VERSION,
                "base_currency": parse_currency(base_currency),
                "members": [],
                "rates": {},
                "expenses": [],
                "payments": [],
                "next_expense_id": 1,
                "next_seq": 1,
            }
        )
        ledger.save(path)
        return ledger

    @classmethod
    def load(cls, path):
        if not os.path.exists(path):
            raise KittyError(
                "no %s in this folder; start one with: python3 -m kitty init EUR" % path
            )
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
        except (OSError, ValueError) as e:
            raise KittyError("could not read %s: %s" % (path, e))
        if not isinstance(data, dict) or data.get("version") != DATA_VERSION:
            raise KittyError("%s does not look like a kitty file" % path)
        return cls(data)

    def save(self, path):
        # Write to a temporary file and swap it in, so a crash mid-write can
        # never leave a half-written kitty.json behind.
        directory = os.path.dirname(os.path.abspath(path))
        fd, tmp = tempfile.mkstemp(prefix=".kitty-", suffix=".tmp", dir=directory)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(self.data, f, indent=2, ensure_ascii=False)
                f.write("\n")
            os.replace(tmp, path)
        except BaseException:
            if os.path.exists(tmp):
                os.remove(tmp)
            raise

    # ---- basics

    @property
    def base(self):
        return self.data["base_currency"]

    @property
    def members(self):
        return self.data["members"]

    def _next_seq(self):
        seq = self.data["next_seq"]
        self.data["next_seq"] = seq + 1
        return seq

    def require_member(self, name):
        if name not in self.members:
            if not self.members:
                raise KittyError("%r is not in the group (the group is empty)" % name)
            raise KittyError(
                "%r is not in the group (members: %s)" % (name, ", ".join(self.members))
            )
        return name

    def to_base(self, amount, currency):
        if currency == self.base:
            return amount
        rate = self.data["rates"].get(currency)
        if rate is None:
            raise KittyError(
                "no exchange rate for %s; set one first, e.g.: python3 -m kitty rate set %s 0.92"
                % (currency, currency)
            )
        return (amount * Decimal(rate)).quantize(CENT, rounding=ROUND_HALF_UP)

    # ---- members

    def add_member(self, name):
        name = validate_name(name)
        if name in self.members:
            raise KittyError("%r is already in the group" % name)
        self.members.append(name)

    def remove_member(self, name):
        self.require_member(name)
        for e in self.data["expenses"]:
            if e["payer"] == name or name in e["shares"]:
                raise KittyError(
                    "cannot remove %r: they are part of expense %d (%s); remove that expense first"
                    % (name, e["id"], e["description"])
                )
        for p in self.data["payments"]:
            if name in (p["from"], p["to"]):
                raise KittyError(
                    "cannot remove %r: they are part of a payment on %s" % (name, p["date"])
                )
        self.members.remove(name)

    # ---- rates

    def set_rate(self, currency, rate_text):
        currency = parse_currency(currency)
        if currency == self.base:
            raise KittyError("%s is the main currency; its rate is always 1" % currency)
        rate = parse_positive_number(rate_text, "rate")
        self.data["rates"][currency] = str(rate)
        return currency, rate

    # ---- expenses

    def _parse_pairs(self, text, option):
        """Parse 'A=30,B=20' into an ordered list of (member, value text)."""
        pairs = []
        seen = set()
        for part in text.split(","):
            if "=" not in part:
                raise KittyError(
                    "%s expects NAME=VALUE pairs separated by commas, got %r" % (option, part)
                )
            name, value = part.split("=", 1)
            name = self.require_member(name.strip())
            if name in seen:
                raise KittyError("%r appears twice in %s" % (name, option))
            seen.add(name)
            pairs.append((name, value))
        return pairs

    def _parse_names(self, text, option):
        names = []
        for part in text.split(","):
            name = self.require_member(part.strip())
            if name in names:
                raise KittyError("%r appears twice in %s" % (name, option))
            names.append(name)
        return names

    def compute_shares(self, amount, base_amount, among=None, exact=None, shares=None, percent=None):
        """Return {member: share in main currency}, adding up to base_amount."""
        given = [x for x in (among, exact, shares, percent) if x is not None]
        if len(given) > 1:
            raise KittyError("use only one of --among, --exact, --shares, --percent")

        if exact is not None:
            pairs = [
                (n, parse_amount(v, "amount for %s" % n))
                for n, v in self._parse_pairs(exact, "--exact")
            ]
            total = sum(v for _, v in pairs)
            if total != amount:
                raise KittyError(
                    "--exact amounts add up to %s but the expense is %s" % (money(total), money(amount))
                )
            # Exact amounts are in the expense's own currency; convert in
            # proportion so the main-currency shares add up exactly.
            return split_proportionally(base_amount, pairs)

        if shares is not None:
            pairs = [
                (n, parse_positive_number(v, "share for %s" % n))
                for n, v in self._parse_pairs(shares, "--shares")
            ]
            return split_proportionally(base_amount, pairs)

        if percent is not None:
            pairs = [
                (n, parse_positive_number(v, "percent for %s" % n))
                for n, v in self._parse_pairs(percent, "--percent")
            ]
            total = sum(v for _, v in pairs)
            if total != HUNDRED:
                raise KittyError("--percent values add up to %s, not 100" % "{:f}".format(total.normalize()))
            return split_proportionally(base_amount, pairs)

        if among is not None:
            names = self._parse_names(among, "--among")
        else:
            names = list(self.members)
            if not names:
                raise KittyError("the group is empty; add people with: python3 -m kitty member add NAME")
        return split_proportionally(base_amount, [(n, Decimal(1)) for n in names])

    def add_expense(self, payer, amount_text, description, currency=None, date=None,
                    category=None, among=None, exact=None, shares=None, percent=None):
        payer = self.require_member(payer)
        amount = parse_amount(amount_text)
        description = description.strip()
        if not description:
            raise KittyError("description cannot be empty")
        currency = parse_currency(currency) if currency else self.base
        date = parse_date(date) if date else today()
        category = (category or "other").strip()
        if not category:
            raise KittyError("category cannot be empty")
        base_amount = self.to_base(amount, currency)
        if base_amount <= 0:
            raise KittyError("amount is too small to be worth anything in %s" % self.base)
        split = self.compute_shares(amount, base_amount, among, exact, shares, percent)

        expense_id = self.data["next_expense_id"]
        self.data["next_expense_id"] = expense_id + 1
        self.data["expenses"].append(
            {
                "id": expense_id,
                "seq": self._next_seq(),
                "date": date,
                "payer": payer,
                "description": description,
                "amount": money(amount),
                "currency": currency,
                "base_amount": money(base_amount),
                "category": category,
                "shares": {n: money(v) for n, v in split.items()},
            }
        )
        return expense_id

    def remove_expense(self, id_text):
        try:
            expense_id = int(id_text)
        except ValueError:
            raise KittyError("expense ID must be a whole number, got %r" % id_text)
        for i, e in enumerate(self.data["expenses"]):
            if e["id"] == expense_id:
                return self.data["expenses"].pop(i)
        raise KittyError("there is no expense with ID %d" % expense_id)

    def list_expenses(self):
        return [
            {k: e[k] for k in ("id", "date", "payer", "description", "amount",
                               "currency", "base_amount", "category", "shares")}
            for e in sorted(self.data["expenses"], key=lambda e: e["id"])
        ]

    # ---- payments

    def add_payment(self, sender, receiver, amount_text, currency=None, date=None):
        sender = self.require_member(sender)
        receiver = self.require_member(receiver)
        if sender == receiver:
            raise KittyError("a payment needs two different people")
        amount = parse_amount(amount_text)
        currency = parse_currency(currency) if currency else self.base
        date = parse_date(date) if date else today()
        base_amount = self.to_base(amount, currency)
        if base_amount <= 0:
            raise KittyError("amount is too small to be worth anything in %s" % self.base)
        self.data["payments"].append(
            {
                "seq": self._next_seq(),
                "date": date,
                "from": sender,
                "to": receiver,
                "amount": money(amount),
                "currency": currency,
                "base_amount": money(base_amount),
            }
        )
        return base_amount

    # ---- reports

    def _events(self):
        """Every expense and payment as (date, seq, description, {member: change})."""
        events = []
        for e in self.data["expenses"]:
            changes = {}
            changes[e["payer"]] = Decimal(e["base_amount"])
            for name, share in e["shares"].items():
                changes[name] = changes.get(name, Decimal(0)) - Decimal(share)
            events.append((e["date"], e["seq"], e["description"], changes))
        for p in self.data["payments"]:
            amount = Decimal(p["base_amount"])
            text = "Payment from %s to %s" % (p["from"], p["to"])
            events.append((p["date"], p["seq"], text, {p["from"]: amount, p["to"]: -amount}))
        events.sort(key=lambda ev: (ev[0], ev[1]))
        return events

    def balance_values(self):
        totals = {name: Decimal(0) for name in self.members}
        for _, _, _, changes in self._events():
            for name, change in changes.items():
                totals[name] = totals.get(name, Decimal(0)) + change
        return totals

    def balances(self):
        return {name: money(v) for name, v in self.balance_values().items()}

    def settle(self):
        """Suggest transfers that bring everyone to zero.

        Repeatedly has the person who owes the most pay the person who is owed
        the most, which keeps the number of transfers small.
        """
        values = self.balance_values()
        debtors = [[n, -v] for n, v in values.items() if v < 0]
        creditors = [[n, v] for n, v in values.items() if v > 0]
        transfers = []
        while debtors and creditors:
            debtors.sort(key=lambda d: -d[1])
            creditors.sort(key=lambda c: -c[1])
            debtor, creditor = debtors[0], creditors[0]
            amount = min(debtor[1], creditor[1])
            transfers.append({"from": debtor[0], "to": creditor[0], "amount": money(amount)})
            debtor[1] -= amount
            creditor[1] -= amount
            debtors = [d for d in debtors if d[1] > 0]
            creditors = [c for c in creditors if c[1] > 0]
        return transfers

    def history(self, name):
        self.require_member(name)
        running = Decimal(0)
        rows = []
        for date, _, description, changes in self._events():
            if name not in changes:
                continue
            running += changes[name]
            rows.append(
                {
                    "date": date,
                    "description": description,
                    "change": money(changes[name]),
                    "balance": money(running),
                }
            )
        return rows

    def report(self):
        totals = {}
        for e in self.data["expenses"]:
            category = totals.setdefault(e["category"], {})
            for name, share in e["shares"].items():
                category[name] = category.get(name, Decimal(0)) + Decimal(share)
        member_order = {n: i for i, n in enumerate(self.members)}
        return {
            cat: {
                n: money(v)
                for n, v in sorted(people.items(), key=lambda kv: member_order.get(kv[0], 0))
            }
            for cat, people in sorted(totals.items())
        }

    def export_rows(self):
        return [
            [e["id"], e["date"], e["payer"], e["description"], e["amount"],
             e["currency"], e["category"], e["base_amount"]]
            for e in sorted(self.data["expenses"], key=lambda e: e["id"])
        ]
"""Command-line interface: python3 -m kitty COMMAND ...

Reports are printed as JSON on standard output. Problems are printed as
"error: ..." on standard error with exit status 1.
"""

import argparse
import csv
import json
import os
import sys

from kitty.ledger import KittyError, Ledger, money

DATA_FILE = "kitty.json"
CSV_COLUMNS = ["id", "date", "payer", "description", "amount", "currency", "category", "base_amount"]


class ArgumentParser(argparse.ArgumentParser):
    """argparse exits with status 2 on bad usage; we want 1 for every error."""

    def error(self, message):
        self.print_usage(sys.stderr)
        self.exit(1, "error: %s\n" % message)


def build_parser():
    parser = ArgumentParser(prog="python3 -m kitty", description="Track shared trip costs.")
    commands = parser.add_subparsers(dest="command", metavar="COMMAND", parser_class=ArgumentParser)
    commands.required = True

    p = commands.add_parser("init", help="start a new kitty with a main currency")
    p.add_argument("currency")

    member = commands.add_parser("member", help="add, remove, or list people")
    member_cmds = member.add_subparsers(dest="action", metavar="ACTION", parser_class=ArgumentParser)
    member_cmds.required = True
    member_cmds.add_parser("add").add_argument("name")
    member_cmds.add_parser("remove").add_argument("name")
    member_cmds.add_parser("list")

    expense = commands.add_parser("expense", help="add, remove, or list expenses")
    expense_cmds = expense.add_subparsers(dest="action", metavar="ACTION", parser_class=ArgumentParser)
    expense_cmds.required = True
    p = expense_cmds.add_parser("add")
    p.add_argument("payer")
    p.add_argument("amount")
    p.add_argument("description", nargs="+")
    p.add_argument("--among", metavar="A,B", help="split equally between only these people")
    p.add_argument("--exact", metavar="A=30,B=20", help="exact amount for each person")
    p.add_argument("--shares", metavar="A=2,B=1", help="split by shares")
    p.add_argument("--percent", metavar="A=60,B=40", help="split by percentages")
    p.add_argument("--currency", help="currency it was paid in (default: main currency)")
    p.add_argument("--date", help="YYYY-MM-DD (default: today)")
    p.add_argument("--category", help='e.g. food (default: "other")')
    expense_cmds.add_parser("list")
    expense_cmds.add_parser("remove").add_argument("id")

    payment = commands.add_parser("payment", help="record someone paying someone back")
    payment_cmds = payment.add_subparsers(dest="action", metavar="ACTION", parser_class=ArgumentParser)
    payment_cmds.required = True
    p = payment_cmds.add_parser("add")
    p.add_argument("sender", metavar="FROM")
    p.add_argument("receiver", metavar="TO")
    p.add_argument("amount")
    p.add_argument("--currency")
    p.add_argument("--date")

    rate = commands.add_parser("rate", help="set an exchange rate")
    rate_cmds = rate.add_subparsers(dest="action", metavar="ACTION", parser_class=ArgumentParser)
    rate_cmds.required = True
    p = rate_cmds.add_parser("set")
    p.add_argument("currency")
    p.add_argument("rate", help="how much one unit is worth in the main currency")

    commands.add_parser("balances", help="who is up or down overall")
    commands.add_parser("settle", help="suggest who should pay whom")
    commands.add_parser("history", help="everything that affected one person").add_argument("name")
    commands.add_parser("report", help="each person's share of spending per category")
    commands.add_parser("export", help="save expenses to a CSV file").add_argument("file")
    return parser


def print_json(value):
    print(json.dumps(value, indent=2, ensure_ascii=False))


def run(args):
    if args.command == "init":
        ledger = Ledger.create(DATA_FILE, args.currency)
        print("Started a new kitty in %s with main currency %s." % (DATA_FILE, ledger.base))
        return

    ledger = Ledger.load(DATA_FILE)
    changed = False

    if args.command == "member":
        if args.action == "add":
            ledger.add_member(args.name)
            changed = True
            print("Added %s." % args.name.strip())
        elif args.action == "remove":
            ledger.remove_member(args.name)
            changed = True
            print("Removed %s." % args.name)
        else:
            print_json(ledger.members)

    elif args.command == "expense":
        if args.action == "add":
            expense_id = ledger.add_expense(
                args.payer, args.amount, " ".join(args.description),
                currency=args.currency, date=args.date, category=args.category,
                among=args.among, exact=args.exact, shares=args.shares, percent=args.percent,
            )
            changed = True
            print(expense_id)
        elif args.action == "remove":
            removed = ledger.remove_expense(args.id)
            changed = True
            print("Removed expense %d (%s)." % (removed["id"], removed["description"]))
        else:
            print_json(ledger.list_expenses())

    elif args.command == "payment":
        base_amount = ledger.add_payment(
            args.sender, args.receiver, args.amount, currency=args.currency, date=args.date
        )
        changed = True
        print("Recorded %s paying %s %s %s." % (args.sender, args.receiver, money(base_amount), ledger.base))

    elif args.command == "rate":
        currency, rate = ledger.set_rate(args.currency, args.rate)
        changed = True
        print("1 %s = %s %s" % (currency, rate, ledger.base))

    elif args.command == "balances":
        print_json(ledger.balances())
    elif args.command == "settle":
        print_json(ledger.settle())
    elif args.command == "history":
        print_json(ledger.history(args.name))
    elif args.command == "report":
        print_json(ledger.report())

    elif args.command == "export":
        if os.path.abspath(args.file) == os.path.abspath(DATA_FILE):
            raise KittyError("exporting to %s would overwrite the kitty itself; pick another name" % DATA_FILE)
        rows = ledger.export_rows()
        try:
            with open(args.file, "w", newline="", encoding="utf-8") as f:
                writer = csv.writer(f)
                writer.writerow(CSV_COLUMNS)
                writer.writerows(rows)
        except OSError as e:
            raise KittyError("could not write %s: %s" % (args.file, e.strerror or e))
        print("Exported %d expense(s) to %s." % (len(rows), args.file))

    if changed:
        try:
            ledger.save(DATA_FILE)
        except OSError as e:
            raise KittyError("could not save %s: %s" % (DATA_FILE, e.strerror or e))


def main(argv=None):
    args = build_parser().parse_args(argv)
    try:
        run(args)
    except KittyError as e:
        print("error: %s" % e, file=sys.stderr)
        return 1
    return 0
import sys

from kitty.cli import main

sys.exit(main())
"""Kitty: track shared trip costs and work out who owes whom."""
